<?php declare(strict_types=1);
require_once __DIR__.'/support/reviewed-document-share.php';
require __DIR__.'/../src/bootstrap.php';
require_once __DIR__.'/mysql-bootstrap.php';
use Kulturhus\Verein\{Database,Registry,Documents,PortalDocuments,EventVouchers,EventVoucherSchema,EventVoucherPdf,WebsiteCalendar};
use Kulturhus\Verein\Tests\MySqlFixture;
set_error_handler(static function($severity,$message,$file,$line){throw new ErrorException($message,0,$severity,$file,$line);});
$n=0;function ok(bool $v,string $m):void{global $n;if(!$v)throw new RuntimeException($m);++$n;echo "PASS $m\n";}
function denied(callable $f,string $m):void{try{$f();}catch(DomainException){ok(true,$m);return;}throw new RuntimeException($m);}
$db=MySqlFixture::connect();Database::migrate($db);EventVoucherSchema::install($db);
$db->exec("INSERT INTO clubs VALUES('a','A'),('b','B'); INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','members',1),('one','a','member',0),('two','a','member',0),('helper','a','member',0),('editor','a','editor',0),('foreign','b','members',1)");
$r=new Registry($db,'admin');$key=fn()=>bin2hex(random_bytes(16));
$p=$r->saveContact(null,0,'person','Mara Muster','shared@example.invalid','');$r->addMembership($p,'','aktiv','2026-01-01');
$p2=$r->saveContact(null,0,'person','Mika Muster','shared@example.invalid','');$r->addMembership($p2,'','passiv','2026-01-01');
foreach(['one'=>$p,'two'=>$p2,'helper'=>$p,'editor'=>$p] as $actor=>$contact)$db->prepare('UPDATE actors SET contact_id=? WHERE id=?')->execute([$contact,$actor]);
$fr=new Registry($db,'foreign');$fp=$fr->saveContact(null,0,'person','Fremder Verein','shared@example.invalid','');$db->prepare("UPDATE actors SET contact_id=? WHERE id='foreign'")->execute([$fp]);
$one=new PortalDocuments($db,'one');$two=new PortalDocuments($db,'two');
ok($one->vouchers()===[],'no vouchers is a valid empty personal document list');
$data=['title'=>'Sommerfest <Test>','start'=>'2026-09-20T18:00','end'=>'2026-09-20T22:00','location'=>'Testgelände','category'=>'verein','description'=>'','activity_kind'=>'event','activity_state'=>'planned'];
$source=$r->saveAppointment(null,0,$data,[]);$s=new EventVouchers($db,'admin');$event=$s->open($source,$key());
$ids=$s->grant($event,[$p],[['label'=>'Getränke','kind'=>'drink','unit'=>'piece','amount'=>'2'],['label'=>'Kuchen','kind'=>'other','unit'=>'eur','amount'=>'3,50']],$key());
$other=$s->grant($event,[$p2],[['label'=>'Nur Mika','kind'=>'food','unit'=>'piece','amount'=>'1']],$key());
$before=MySqlFixture::rows($db,'event_vouchers');$docs=$one->vouchers();
ok(count($docs)===1&&$docs[0]['open_cards']===3&&$docs[0]['can_download'],'allocated vouchers immediately appear once per event with PDF link');
ok($docs[0]['contact_id']===$p&&$docs[0]['benefits']===['Getränke · 2 Stück','Kuchen · 3,50 €'],'labels quantities and euro credit belong only to own profile');
ok($two->vouchers()[0]['benefits']===['Nur Mika · 1 Stück'],'shared email never merges different member vouchers');
ok((int)$db->query('SELECT COUNT(*) FROM event_voucher_outbox')->fetchColumn()===0,'document availability does not require mail or send anything');
ok((new PortalDocuments($db,'foreign'))->vouchers()===[],'different club never appears in personal documents');
denied(fn()=>(new PortalDocuments($db,'admin'))->vouchers(),'unlinked administrator does not get all members in own documents');
$s->configure($event,1,true,['helper'],$key());
ok((new PortalDocuments($db,'helper'))->vouchers()[0]['benefits']===$docs[0]['benefits'],'event helper sees only own documents despite redemption authority');
$db->prepare("UPDATE actors SET contact_id=? WHERE id='admin'")->execute([$p]);
ok((new PortalDocuments($db,'admin'))->vouchers()[0]['benefits']===$docs[0]['benefits'],'linked administrator still sees only own documents');
denied(fn()=>(new PortalDocuments($db,'editor'))->vouchers(),'editor excluded even with contact binding');
denied(fn()=>EventVoucherPdf::file($db,'one',$event,$p2),'manipulated PDF recipient cannot expose another member');
denied(fn()=>EventVoucherPdf::file($db,'foreign',$event,$p),'other club cannot download personal PDF');
$doc=(new Documents($db,'admin'))->upload('bestaetigung.txt','Persönliche Bestätigung',['title'=>'Ehrenamtsbestätigung','scope'=>'orga','kind'=>'other'],$key());
ownReviewedDocumentShare(new PortalDocuments($db,'admin'),new Documents($db,'admin'),$doc,$p,true);
ok($one->shares()[0]['id']===$doc&&$one->file($doc)['bytes']==='Persönliche Bestätigung'&&$one->listing()===[],'shared certificates and existing invoice API remain available');
require_once __DIR__.'/../src/Web/View.php';$_SESSION=['actor'=>'one','csrf'=>'synthetic'];$websiteCalendar=null;
ob_start();require __DIR__.'/../views/Documents/portal-documents.php';$html=ob_get_clean();
ok(str_contains($html,'Ehrenamtsbestätigung')&&str_contains($html,'Beitragsrechnungen')&&str_contains($html,'Meine Gutscheine'),'same document page contains invoices certificates and vouchers');
ok(str_contains($html,'Gutschein-PDF herunterladen')&&str_contains($html,'voucher_pdf='.$p)&&!str_contains($html,'voucher_pdf='.$p2),'download link is for authenticated own contact');
ok(str_contains($html,'Sommerfest &lt;Test&gt;')&&!str_contains($html,'Nur Mika'),'event title escaped and no other member information rendered');
ok(MySqlFixture::rows($db,'event_vouchers')===$before,'rendering documents does not change balances or create duplicate vouchers');
$s->change($event,$ids[0],1,'redeem','1','',$key());
ok($one->vouchers()[0]['open_cards']===2&&$one->vouchers()[0]['benefits'][0]==='Getränke · 1 Stück','redemption immediately reduces personal document balance');
$s->change($event,$ids[0],2,'redeem','1','',$key());$s->change($event,$ids[1],1,'revoke','','Gelöscht',$key());
ok(!$one->vouchers()[0]['can_download']&&$one->vouchers()[0]['open_cards']===0,'used or revoked vouchers are not downloadable as open tickets');
$s->change($event,$other[0],1,'revoke','','Gelöscht',$key());ok($two->vouchers()===[],'deleted-only vouchers disappear from personal document list');
$row=['id'=>10,'external_id'=>'','title'=>'Website-Fest','summary'=>'','venue_name'=>'Bühne','venue_address'=>'','path'=>'/fest/','status'=>'published','start_at'=>strtotime('2026-09-21T16:00:00Z'),'end_at'=>strtotime('2026-09-21T20:00:00Z')];
$website=new WebsiteCalendar('a',static fn()=>['complete'=>true,'rows'=>[$row]]);$ws=new EventVouchers($db,'admin',$website);$web=$ws->open('website:10',$key());$ws->grant($web,[$p],[['label'=>'Essen','kind'=>'food','unit'=>'piece','amount'=>'1']],$key());
ok(count($one->vouchers($website))===2&&$one->vouchers($website)[0]['can_download'],'website and internal events appear separately');
$moved=new WebsiteCalendar('a',static fn()=>['complete'=>true,'rows'=>[array_replace($row,['title'=>'Neuer Titel'])]]);
ok($one->vouchers($moved)[0]['title']==='Neuer Titel','document title follows current website event');
$unavailable=new WebsiteCalendar('a',static fn()=>['complete'=>false,'rows'=>[]]);
ok(!$one->vouchers($unavailable)[0]['can_download']&&$one->vouchers($unavailable)[0]['notice']!=='','unavailable calendar fails closed without losing other documents');
$ws->configure($web,1,false,[],$key());ok(!$one->vouchers($website)[0]['can_download'],'closed event has no active PDF link');
$ws->configure($web,2,true,[],$key());
$db->prepare('UPDATE contacts SET archived_at=? WHERE club_id=? AND id=?')->execute([gmdate('c'),'a',$p]);
denied(fn()=>$one->vouchers($website),'archived own profile denied');
$db->prepare('UPDATE contacts SET archived_at=NULL WHERE club_id=? AND id=?')->execute(['a',$p]);$db->exec("UPDATE actors SET active=0 WHERE id='one'");
denied(fn()=>$one->vouchers($website),'disabled account denied');
ok(!MySqlFixture::foreignKeyErrors($db),'relational integrity retained');
echo "Passed $n personal document checks\n";
